function u(e){return String(e||"").split(/[|｜]/u).map(r=>r.replace(/\s+/gu," ").trim()).filter(Boolean)}function t(e){return e.normalize("NFKC").replace(/[\u064B-\u065F\u0670]/gu,"").replace(/\s+/gu," ").trim().toLocaleLowerCase("ar")}function w(e){const r=new Set;return u(e).filter(n=>{const a=t(n);return r.has(a)?!1:(r.add(a),!0)}).join(" | ")}function h(e,r){const n=u(r);if(!n.length)return w(e);const a=new Set(n.map(t)),c=n.map(s=>s.replace(/^(?:مؤسسة|شركة)\s+/u,"").trim()).filter((s,i)=>s&&t(s)!==t(n[i])),o=new Set(c.map(t)),f=u(e),l=f.some(s=>o.has(t(s))&&!a.has(t(s))),p=l?c:n,S=new Set([...a,...l?o:[]]),m=new Set;return[...f.filter(s=>{const i=t(s);return S.has(i)||m.has(i)?!1:(m.add(i),!0)}),...p].join(" | ")}function d(e,r){const n=new Set(u(r).map(t)),a=new Set;return u(e).filter(c=>{const o=t(c);return n.has(o)||a.has(o)?!1:(a.add(o),!0)}).join(" | ")}export{h as c,w as n,d as s};
